demos = task_data['demo_pairs']

all_demos_verified = []

for i, demo in enumerate(demos):
    inp = demo['input']
    out = demo['output']
    h, w = len(inp), len(inp[0])

    sep_row = None
    sep_col = None

    # Find separator
    for r in range(1, h):
        if len(set(inp[r])) == 1 and inp[r][0] != 0:
            sep_row = r
            break

    if sep_row is None:
        for c in range(1, w):
            if all(inp[r][c] == inp[0][c] for r in range(h)) and inp[0][c] != 0:
                sep_col = c
                break

    sep_value = inp[sep_row][0] if sep_row else inp[0][sep_col]

    if sep_row is not None:
        left = inp[:sep_row]
        right = inp[sep_row+1:]
    else:
        left = [row[:sep_col] for row in inp]
        right = [row[sep_col+1:] for row in inp]

    # Count mismatch
    mismatch = 0
    match_count = 0

    if sep_row is not None:
        out_h, out_w = len(out), len(out[0])
        for i in range(min(out_h, len(left))):
            for j in range(min(out_w, len(left[0]))):
                both_nonzero = left[i][j] != 0 and right[i][j] != 0
                is_two = out[i][j] == 2
                if both_nonzero != is_two:
                    mismatch += 1
    else:
        for i in range(min(len(out), len(left))):
            for j in range(min(len(out[0]), len(left[0]))):
                both_nonzero = left[i][j] != 0 and right[i][j] != 0
                is_two = out[i][j] == 2
                if both_nonzero != is_two:
                    mismatch += 1
    match_count = (len(left) * len(left[0])) - mismatch

    all_demos_verified.append({
        "demo": i,
        "sep_row": sep_row, "sep_col": sep_col, "sep_val": sep_value,
        "match_count": match_count,
        "total": len(left) * len(left[0]),
        "mismatch": mismatch
    })
    print(f"Demo {i}: sep={sep_row}h or {sep_col}v, {match_count}/{len(left) * len(left[0])} match")

# Verify all demos pass
total_match = sum(d['match_count'] for d in all_demos_verified)
total_cells = sum(d['total'] for d in all_demos_verified)
print(f"\nOverall: {total_match}/{total_cells} cells correctly predicted")

