    if sep_row is None:
        for c in range(1, w):
            if all(grid[r][c] == grid[0][c] for r in range(h)) and grid[0][c] != 0:
                sep_col = c

    output = [[0] * w for _ in range(h)]

    if sep_row is not None:
        left = grid[:sep_row]
        right = grid[sep_row+1:]
        out_h = min(len(left), len(right))
